// Webhook integrity check (opt-in via WEBHOOK_INTEGRITY_CHECK_ENABLED=1).
// Telegram Trigger handles HMAC via its secretToken option (set on the
// trigger node itself). This Code node is the second defense layer:
// reject malformed payloads that lack the fields downstream nodes expect.
//
// To enable: set the n8n env var WEBHOOK_INTEGRITY_CHECK_ENABLED to '1'.
// To disable: leave the env var unset (default). The node passes through.

const enabled = $env.WEBHOOK_INTEGRITY_CHECK_ENABLED === '1';
if (!enabled) {
  return [{ json: $input.first().json }];
}

const item = $input.first().json;
const message = item?.message ?? item;

if (!message || typeof message !== 'object') {
  throw new Error('Webhook integrity check failed: no message object');
}
if (typeof message.from?.id !== 'number' && typeof message.from?.id !== 'string') {
  throw new Error('Webhook integrity check failed: missing message.from.id');
}
if (typeof message.chat?.id !== 'number' && typeof message.chat?.id !== 'string') {
  throw new Error('Webhook integrity check failed: missing message.chat.id');
}
if (typeof message.text !== 'string' && typeof message.caption !== 'string') {
  throw new Error('Webhook integrity check failed: no text or caption');
}

return [{ json: item }];

// Rate limit (opt-in via RATE_LIMIT_ENABLED=1).
// Per-chat-id 60 requests in a 5-minute window. Tracked in workflow
// static data (per-instance). For clustered n8n deployments or higher
// throughput, use Nginx limit_req_zone or Cloudflare WAF instead.
//
// To enable: set the n8n env var RATE_LIMIT_ENABLED to '1'.
// To disable: leave the env var unset (default). The node passes through.
//
// Concurrency note: $getWorkflowStaticData is not atomic. Under heavy
// burst load the count can over-shoot the limit by a few percent. For
// hard limits use a reverse proxy or Redis INCR + EXPIRE.

const enabled = $env.RATE_LIMIT_ENABLED === '1';
if (!enabled) {
  return [{ json: $input.first().json }];
}

const item = $input.first().json;
const message = item?.message ?? item;
const chatId = message?.chat?.id ?? message?.from?.id ?? 'unknown';
const bucketKey = `chat:${chatId}`;

const data = $getWorkflowStaticData('global');
const buckets = data.rateBuckets ?? {};
const now = Date.now();
const WINDOW_MS = 5 * 60 * 1000;
const LIMIT = 60;
const MAX_BUCKETS = 5000;

const bucket = buckets[bucketKey] ?? { count: 0, windowStart: now };
if (now - bucket.windowStart > WINDOW_MS) {
  bucket.count = 0;
  bucket.windowStart = now;
}
bucket.count++;
buckets[bucketKey] = bucket;

// Bound the map: evict expired entries when full
if (Object.keys(buckets).length > MAX_BUCKETS) {
  const cutoff = now - WINDOW_MS;
  for (const k of Object.keys(buckets)) {
    if (buckets[k].windowStart < cutoff) delete buckets[k];
  }
}
data.rateBuckets = buckets;

if (bucket.count > LIMIT) {
  throw new Error(`Rate limit exceeded for ${bucketKey}: ${bucket.count} requests in 5 min window`);
}

return [{ json: item }];

// Idempotency check (opt-in via IDEMPOTENCY_ENABLED=1).
// Telegram retries on 5xx. Without dedup, the workflow fires twice and
// writes Memory twice. This node holds a 5-minute in-memory window of
// seen update_ids and short-circuits duplicates.
//
// To enable: set the n8n env var IDEMPOTENCY_ENABLED to '1'.
// To disable: leave the env var unset (default). The node passes through.
//
// Concurrency note: $getWorkflowStaticData is not atomic and not cluster-
// aware. Two simultaneous fires of the same update_id may both pass.
// For production scale, swap the staticData block for Redis SET NX EX 300.

const enabled = $env.IDEMPOTENCY_ENABLED === '1';
if (!enabled) {
  return [{ json: $input.first().json }];
}

const item = $input.first().json;
const message = item?.message ?? item;
const updateId = item?.update_id ?? message?.update_id;
const messageId = message?.message_id;
const idempotencyKey = updateId ? `tg-update:${updateId}` : (messageId ? `tg-msg:${messageId}` : null);

if (!idempotencyKey) {
  // No dedup key available, pass through
  return [{ json: item }];
}

const data = $getWorkflowStaticData('global');
const seen = data.seenKeys ?? {};
const now = Date.now();
const WINDOW_MS = 5 * 60 * 1000;

// Purge expired entries
for (const k of Object.keys(seen)) {
  if (now - seen[k] > WINDOW_MS) delete seen[k];
}

if (seen[idempotencyKey]) {
  // Duplicate, short-circuit by returning empty array
  return [];
}
seen[idempotencyKey] = now;
data.seenKeys = seen;

return [{ json: item }];

// Extract a stable customer key from the inbound Telegram message.
// Priority: email in message body > Telegram user ID > Telegram chat ID.
// We never produce 'tg:undefined' which would collapse all anonymous
// senders (channel posts, forwarded messages without sender) into one
// shared customer entity.

const body = $input.first().json;
const message = body?.message ?? body;
const text = message?.text ?? message?.caption ?? '';
const tgUserId = message?.from?.id;
const tgUsername = message?.from?.username;
const tgFirstName = message?.from?.first_name ?? '';
const chatId = message?.chat?.id;

// Email regex, RFC-5322-ish but conservative
const emailRe = /[\w!#$%&'*+/=?^_`{|}~.-]+@[\w.-]+\.[a-zA-Z]{2,}/;
const emailMatch = text.match(emailRe);
const customerEmail = emailMatch ? emailMatch[0].toLowerCase() : null;

// Customer key resolution in fallback order:
//   1. email if visible in the message text
//   2. Telegram user id (when from.id is present)
//   3. Telegram chat id (always present on valid messages, last-resort)
// If all three are missing the message is malformed and we fail loud.
let customerKey;
let customerLabel;
if (customerEmail) {
  customerKey = customerEmail;
  customerLabel = customerEmail;
} else if (tgUserId !== undefined && tgUserId !== null) {
  customerKey = `tg:${tgUserId}`;
  customerLabel = tgUsername ? `@${tgUsername}` : (tgFirstName || `tg:${tgUserId}`);
} else if (chatId !== undefined && chatId !== null) {
  customerKey = `chat:${chatId}`;
  customerLabel = `chat:${chatId}`;
} else {
  throw new Error('Cannot build customer key: message has no email, no from.id, and no chat.id');
}

return [{
  json: {
    customerKey,
    customerEmail,
    customerLabel,
    tgUserId,
    tgUsername,
    tgFirstName,
    chatId,
    messageText: text,
    receivedAt: new Date().toISOString(),
  },
}];

// Build a structured dossier the LLM can use as background.

const custKey = $('Extract Customer Key').item.json.customerKey;
const custLabel = $('Extract Customer Key').item.json.customerLabel || '(unknown)';
const messageText = $('Extract Customer Key').item.json.messageText;

// If known customer: pull observations from entity.open
let observations = [];
let entityType = 'customer';
let firstSeen = null;
try {
  const dossier = $('Memory: Customer Dossier').first()?.json;
  const entity = dossier?.entity ?? dossier?.data ?? dossier;
  observations = entity?.observations ?? [];
  entityType = entity?.entityType ?? 'customer';
  firstSeen = entity?.createdAt ?? entity?.validFrom;
} catch (e) {
  // First-time customer, no dossier yet
}

const obsList = observations.length
  ? observations.slice(-10).map((o, i) => {
      const content = o.content ?? o.text ?? JSON.stringify(o).slice(0, 200);
      const at = o.createdAt ?? o.observedAt ?? '';
      return `${i + 1}. [${at}] ${content}`;
    }).join('\n')
  : '(this is a new customer, no prior tickets on file)';

const systemPrompt = `You are a friendly support agent for our company.\n\nCustomer: ${custLabel}\nFirst contact: ${firstSeen ?? 'today'}\nPrior interactions (most recent first):\n${obsList}\n\nReply concisely. Reference past tickets when it adds value ("I see this is your second time asking about X, let me get to the bottom of it."). If the question is unclear, ask one clarifying question. If the issue is technical and beyond a one-line answer, offer to escalate to a human and tell the user that you'll log the ticket.`;

return [{
  json: {
    customerKey: custKey,
    customerLabel: custLabel,
    messageText,
    systemPrompt,
    observationCount: observations.length,
  },
}];

// LLM Fallback Reply: fires when OpenAI Reply or Anthropic Reply errors.
// Builds a graceful customer-facing reply and an error-learn payload that
// downstream nodes (Telegram Reply, Memory: Learn Error) consume.
//
// The error pin from a node with onError=continueErrorOutput delivers
// $json.error.message (and other error fields). $error.message does not
// exist as a global in n8n, despite being often quoted online.

const errorRaw = $input.first().json;
const provider = $('Set Provider').item.json.provider ?? 'unknown';
const errorMessage = errorRaw?.error?.message
  ?? errorRaw?.error?.name
  ?? errorRaw?.message
  ?? JSON.stringify(errorRaw).slice(0, 200);

const customerKey = $('Extract Customer Key').item.json.customerKey;
const customerLabel = $('Extract Customer Key').item.json.customerLabel;
const messageText = $('Extract Customer Key').item.json.messageText;

const fallbackText = `Sorry, our system is briefly unavailable. We will get back to you within an hour.`;

return [{
  json: {
    replyText: fallbackText,
    provider,
    isFallback: true,
    errorMessage: String(errorMessage),
    customerKey,
    customerLabel,
    messageText,
  },
}];

// Normalize LLM output across providers into a single field `replyText`.
// OpenAI:    $json.choices[0].message.content
// Anthropic: $json.content[0].text

const raw = $input.first().json;
let replyText = '';

if (raw?.choices?.[0]?.message?.content) {
  replyText = raw.choices[0].message.content;
} else if (Array.isArray(raw?.content) && raw.content[0]?.text) {
  replyText = raw.content[0].text;
} else if (raw?.message?.content) {
  replyText = raw.message.content;
} else if (raw?.text) {
  replyText = raw.text;
} else if (raw?.reply) {
  replyText = raw.reply;
} else {
  replyText = '(LLM returned no text, check provider response shape)';
}

return [{
  json: {
    replyText: String(replyText).trim(),
    provider: $('Set Provider').item.json.provider,
    isFallback: false,
  },
}];
